  'settings.computerUseDesc': 'Agenci mogą odczytywać okna innych aplikacji oraz klikać, pisać i naciskać w nich klawisze. Zrzuty ekranu i tekst okien trafiają do dostawcy modelu agenta. Domyślnie wyłączone.',
  'settings.computerUseHelper': 'Program pomocniczy',
  'settings.computerUseHelperDesc': 'Mały program, który na tym komputerze odczytuje i obsługuje inne aplikacje w imieniu wmux.',
  'settings.computerUseHelperReady': 'Gotowy',
  'settings.computerUseHelperMissing': 'Jeszcze nie w tej wersji',
