  'settings.computerUseHelperElevated': 'Niedostępne: wmux działa jako administrator',
  'settings.computerUseHelperDamaged': 'Uszkodzony: zainstaluj wmux ponownie',
  'settings.computerUseStopKey': 'Klawisz zatrzymania',
  'settings.computerUseStopKeyDesc': 'Naciśnij go w dowolnym miejscu, aby zatrzymać wszystkich agentów naraz. Gdy włączone jest Pytaj o każdą aplikację, potem muszą ponownie poprosić o każdą aplikację.',
  'settings.computerUseStopKeyUnavailable': 'Niedostępny',
  'settings.computerUseStopKeyUnavailableDesc': 'Inna aplikacja używa tego skrótu, więc wmux nie może przejąć klawisza zatrzymania.',
  'settings.computerUseStopKeyUnavailableNote': 'Dopóki klawisz zatrzymania jest niedostępny, agenci nie mogą obsługiwać aplikacji; nadal mogą je oglądać. Zamknij aplikację, która używa {key}. wmux spróbuje ponownie przy następnym wywołaniu agenta lub po ponownym otwarciu tej karty.',
  'settings.computerUseSafety': 'Bezpieczeństwo',
  'settings.computerUseConsent': 'Pytaj o każdą aplikację',
  'settings.computerUseConsentDesc': 'Gdy agent po raz pierwszy chce zobaczyć lub obsłużyć aplikację, wmux pyta Ciebie; odpowiedź obowiązuje do ponownego uruchomienia wmux lub naciśnięcia klawisza zatrzymania. Wyłączone: agenci mogą używać każdej niezablokowanej aplikacji.',
  'settings.computerUseBlocked': 'Nigdy niedozwolone',
  'settings.computerUseBlockedDesc': 'Menedżery haseł, sam wmux oraz systemowe okna logowania i uprawnień administratora.',
  'settings.computerUseRestartNote': 'Działający już agenci uwzględnią zmianę po ponownym uruchomieniu.',
  'settings.computerUseNoHelperNote': 'Ta wersja wmux nie zawiera jeszcze programu pomocniczego dla tego systemu, więc nie można włączyć sterowania komputerem. Pojawi się w późniejszym wydaniu.',
  'settings.computerUseUnsupportedNote': 'wmux nie ma programu pomocniczego dla tego systemu, więc nie można włączyć sterowania komputerem.',
  'settings.computerUseElevatedNote': 'wmux działa jako administrator, a sterowanie komputerem nie uruchamia się z podwyższonymi uprawnieniami, bo mogłoby sterować aplikacjami administratora. Uruchom wmux ponownie bez opcji „Uruchom jako administrator”.',
  'settings.computerUseDamagedNote': 'Program pomocniczy nie pasuje do tej wersji wmux (jest uszkodzony, częściowo zaktualizowany lub zmieniony przez program antywirusowy), więc agenci nie mogą go używać. Zainstaluj wmux ponownie.',
  'settings.computerUseHelperUnsignedNote': 'Ten program pomocniczy nie ma podpisu kodu; Windows Defender lub SmartScreen mogą o nim ostrzegać.',
  'settings.computerUseStopKeyNoHelperDesc': 'Nieaktywny: ta wersja nie ma programu pomocniczego, więc nie ma czego zatrzymywać.',
  'settings.computerUseStopKeyDamagedDesc': 'Nieaktywny: program pomocniczy jest uszkodzony, więc nie ma czego zatrzymywać.',
  'settings.computerUseStopKeyOffDesc': 'Aktywny tylko, gdy sterowanie komputerem jest włączone; wtedy naciśnięcie go w dowolnym miejscu zatrzymuje wszystkich agentów naraz.',
  'settings.computerUseOnWithoutHelperNote': 'Sterowanie komputerem jest włączone, ale ta wersja nie ma programu pomocniczego: agenci nadal widzą to narzędzie, a każde wywołanie kończy się błędem. Na razie je wyłącz.',
  'settings.computerUseSaveFailed': 'Nie udało się zapisać ustawienia: {error}',
  'settings.computerUseOverlay': 'Pokazuj kursor agenta i obwódkę',
  'settings.computerUseOverlayDesc': 'Gdy agent obsługuje aplikację, drugi kursor pokazuje, gdzie działa, a obwódka zaznacza okno.',
  'settings.computerUsePermissions': 'Uprawnienia',
  'settings.computerUsePermissionsOffDesc': 'Włącz sterowanie komputerem, aby zobaczyć, na co pozwala macOS.',
  'settings.computerUseAccessibility': 'Dostępność',
  'settings.computerUseAccessibilityDesc': 'Potrzebna do odczytu i naciskania kontrolek, klikania i pisania.',
  'settings.computerUseScreenRecording': 'Nagrywanie ekranu',
  'settings.computerUseScreenRecordingDesc': 'Potrzebne do zrzutów okien aplikacji.',
  'settings.computerUsePermissionGranted': 'Dozwolone',
  'settings.computerUsePermissionMissing': 'Niedozwolone',
  'settings.computerUseAccess': 'Dostęp',
  'settings.computerUseAccessDesc': 'macOS nadaje te uprawnienia aplikacji pomocniczej „wmux Computer Use”, nie samemu wmux.',
  'settings.computerUseRequestAccess': 'Poproś o dostęp',
  'settings.computerUseShowHelper': 'Pokaż program pomocniczy w Finderze',
  'settings.computerUseResetAccess': 'Zresetuj dostęp',
  'settings.computerUseResetKeep': 'Zostaw',
  'settings.computerUseResetConfirm': 'Reset dostępu usuwa program pomocniczy z list Dostępność i Nagrywanie ekranu, także wpis, który wygląda na włączony, ale już nie działa. Potem zezwól ponownie przyciskiem Poproś o dostęp.',
