  // Orchestrator (command deck brain) settings
  'settings.orchestrator': 'Orkiestrator',
  'settings.orchestratorBrain': 'Mózg orkiestratora',
  'settings.orchestratorBrainDesc':
    'Który runtime agenta napędza Command Deck. Mózg terminalowy jest domyślny — steruje Twoim własnym plikiem binarnym claude na Twojej subskrypcji. Hermes (ACP) wymaga zainstalowanego i uwierzytelnionego Hermes Agent CLI na tej maszynie — najpierw uruchom jego własną konfigurację. Obowiązuje od następnej tury mózgu; każdy mózg trzyma własną historię rozmowy.',
  'settings.orchestratorBrainClaude': 'Claude Code (SDK)',
  'settings.orchestratorBrainClaudePty': 'Claude Code (terminal, domyślny) — subskrypcja',
  'settings.orchestratorBrainHermes': 'Hermes Agent (ACP) — eksperymentalny',
  // D2 — role → agent/model enforcement editor (Settings › Orchestrator).
  'settings.roleBindings': 'Rola → wymuszenie modelu',
  'settings.roleBindingsDesc':
    'Przypnij agenta i model do każdej roli. Uruchomienia, które sam wmux składa dla panelu niosącego tę rolę, ruszają z powiązanym modelem: uruchomienie agenta zlecane przez orkiestratora, zaszyte polecenie panelu projektu, którego liść wmux.json deklaruje rolę, oraz polecenie wznowienia panelu. Launcher, który sam wpisujesz w terminalu, nie jest przepisywany. Zostaw wiersz pusty, aby rola pozostała niepowiązana.',
  'settings.roleBindingAgentPlaceholder': 'agent',
  'settings.roleBindingModelPlaceholder': 'model (opcjonalny)',
  'settings.roleBindingArgsPlaceholder': 'dodatkowe argumenty (opcjonalne)',
  'settings.roleBindingAgentLabel': 'agent roli {role}',
  'settings.roleBindingModelLabel': 'model roli {role}',
  'settings.roleBindingArgsLabel': 'dodatkowe argumenty roli {role}',
  'settings.roleBindingHintNoAgent':
    'Wybierz też agenta — sam model nie jest wymuszany (wmux nie wie, czyją flagą --model to jest).',
  'settings.roleBindingHintNoGrammar':
    'wmux nie ma zweryfikowanej flagi --model dla {agent}, więc model jest ignorowany. Dodatkowe argumenty nadal obowiązują.',
  'settings.roleBindingHintInert': 'Dodaj model, effort, pomijanie uprawnień, świeży kontekst lub dodatkowe argumenty — sam agent nic nie wymusza.',
  'settings.roleBindingHintFreshContextInert':
    'Świeży kontekst dla każdego zadania działa tylko z agentem claude lub codex; dla tej roli nic nie robi.',
  'settings.roleBindingEffortLabel': 'Effort: {role}',
  'settings.roleBindingEffortDefault': 'Effort: domyślny',
  'settings.roleBindingSkipPermissions': 'Pomijaj uprawnienia',
  'settings.roleBindingFreshContext': 'Świeży kontekst dla każdego zadania',
  'settings.roleBindingFreshContextTooltip':
    'Gdy ten panel dostaje NOWE zadanie (terminal_send orkiestratora z new_task albo nowe send_message od innego agenta), wmux najpierw wpisuje {command}, aby rozmowa z poprzedniego zadania nie przechodziła dalej. Nigdy przy kontynuacji ani odpowiedzi. Pomijane, gdy agent pracuje albo panel ma jeszcze inne otwarte zadania agentów.',
  'settings.roleBindingRefreshModels': 'Odśwież modele',
  'settings.rolePresetApply': 'Zastosuj preset {role}',
  'settings.rolePresetApplied': 'Preset {role} zastosowany',
  'settings.rolePresetApplyBypass':
    'Zastosuj preset {role} (pomija pytania o uprawnienia)',
  'settings.rolePresetTooltipNoSkip':
    'Ustawia tę rolę na wysiłek {tier}, zachowując wybranego agenta, model i dodatkowe argumenty. Ten agent nie ma zweryfikowanej flagi pomijania uprawnień, więc pytania o uprawnienia pozostają włączone.',
  'settings.rolePresetConfirmBypass':
    'Zastosować preset {role}? Włącza pomijanie uprawnień: każde uruchomienie {role}, także zadania fan-out kierowane do {role}, będzie edytować pliki i uruchamiać polecenia bez pytania.',
  'settings.rolePresetTooltip':
    'Ustawia tę rolę na wysiłek {tier} ORAZ włącza pomijanie uprawnień: każde uruchomienie {role}, także zadania fan-out kierowane do {role}, działa bez pytań o uprawnienia. Zachowuje wybranego agenta, model i dodatkowe argumenty; uzupełnia tylko pustego agenta (agy) lub model. W agy wysiłek jest końcówką nazwy modelu, więc model Flash przechodzi na wariant {tier}, a każdy inny model zostaje bez zmian. Narzędzia, skille i MCP nie są per rola dla agy; pozostają wspólne dla wszystkich ról.',
  'settings.tabTokens': 'Zużycie tokenów',
  'settings.tokenProfile': 'Profil',
  'settings.tokenProfileDesc':
    'Skrót, który zapisuje model i effort w powiązaniach ról. Agenci, dodatkowe argumenty i uprawnienia nigdy nie są zmieniane, a każde powiązanie można dalej edytować w Role i fan-out.',
  'settings.tokenProfileBalanced': 'Zrównoważony',
  'settings.tokenProfileFull': 'Pełny',
  'settings.tokenProfileCoding': 'Kodowanie',
  'settings.tokenProfileFullDesc': 'Najlepsze modele, wysoki effort, wszystkie narzędzia wmux. Maksimum możliwości i tokenów.',
  'settings.tokenProfileCodingDesc': 'Mocny planista, wykonawcy ze średnim effortem, narzędzia core wmux (bez przeglądarki).',
  'settings.tokenProfileBalancedDesc': 'Średni planista i builder, sprawdzający z niskim effortem, tylko narzędzia danej roli.',
  'settings.tokenProfileMinimalDesc': 'Najniższy effort w każdej roli i tylko narzędzia danej roli. Najmniej tokenów; dla jednego dobrze określonego projektu.',
  'settings.tokenProfileMinimal': 'Minimalny',
