  'settings.imagePasteDesc': 'Jak schowek zawierający wyłącznie obraz trafia do panelu. Tryb automatyczny pozwala agentom czytającym schowek samodzielnie (Claude Code) pokazać prawdziwy obraz w treści, a w pozostałych przypadkach wkleja ścieżkę pliku tymczasowego. Wklejanie tekstu pozostaje bez zmian.',
