  'settings.imeResidueGuardDesc': 'Chroni przed narzędziami głosowego wejścia, które destrukcyjnie zastępują pozostały tekst IME. Zostaw wyłączone, chyba że używasz takiego narzędzia — czyszczenie może zmylić niektóre IME.',
  'settings.hiddenPaneRetention': 'Wstrzymaj renderowanie ukrytych paneli',
  'settings.hiddenPaneRetentionDesc': 'Domyślnie włączone. Ukryte panele wstrzymują renderowanie ekranu, podczas gdy wszystko dalej działa — wyjście jest przechwytywane przez demona, a panel nadrabia po przełączeniu z powrotem (krótko pokazuje „nadrabianie”). Wyłącz, aby renderować każdy ukryty panel nieprzerwanie; to kosztuje realny CPU na każdy zajęty ukryty panel. Tylko sesje demona; sesje trybu lokalnego zawsze renderują.',
  'settings.coldPark': 'Wyładuj bezczynne ukryte obszary robocze',
  'settings.inlineImages': 'Obrazy w terminalu',
  'settings.inlineImagesDesc': 'Rysuje w panelu obrazy, które programy terminalowe wypisują w formacie sixel lub protokołem obrazów iTerm2 (OSC 1337). Każdy panel przechowuje najwyżej 64 MB obrazów; starsze zastępuje symbol zastępczy. Wyłącz, aby ignorować obrazy i zwolnić tę pamięć.',
  'settings.coldParkDesc': 'Domyślnie włączone. Obszar roboczy, na który nie patrzysz od kilku minut, ma wyładowywane terminale, aby zwolnić pamięć — RAM przestaje rosnąć wraz z liczbą otwartych obszarów roboczych. Sesje nadal działają w demonie; powrót przeładowuje obszar roboczy i odtwarza jego ekran z demona. Wyłącz, aby każdy obszar roboczy pozostał wczytany dla natychmiastowego pokazania. Tylko sesje demona.',
  'settings.browserBackend': 'Silnik przeglądarki',
  'settings.browserBackendDesc': 'Dokąd trafiają otwarcia przeglądarki inicjowane przez agenta. Wbudowany otwiera osadzone panele przeglądarki wewnątrz wmuxa z pełnym zestawem automatyzacji (klikanie, zrzuty ekranu, wyciąganie danych). Zewnętrzny wysyła otwarcia do Twojej prawdziwej, zalogowanej domyślnej przeglądarki — działa tylko otwieranie i nawigacja; głęboka automatyzacja (klik, zrzut ekranu itd.) jest wyłączona i wmux nie uruchamia osadzonej przeglądarki. Zewnętrzny jest globalny: każdy obszar roboczy otwiera we wspólnej sesji przeglądarki, więc dowolny agent może tam otworzyć kartę. Chrome uruchamia dedykowaną, prawdziwą instancję Chrome z własnym trwałym profilem — zaloguj się raz, a sesje zostają; działa w pełni oddzielnie od Twojej codziennej przeglądarki, z pełnym zestawem automatyzacji. Każdy obszar roboczy może powiązać własny profil Chrome w menu kontekstowym karty obszaru roboczego (osobne logowania per obszar).',
  'settings.browserBackendBuiltin': 'Wbudowany (osadzone panele)',
  'settings.browserBackendExternal': 'Zewnętrzny (Twoja domyślna przeglądarka)',
  'settings.browserBackendChrome': 'Chrome (dedykowana przeglądarka agenta)',
  'chromeProfiles.menuLabel': 'Profil Chrome',
  'chromeProfiles.defaultProfile': 'Profil domyślny',
  'chromeProfiles.newProfile': 'Nowy profil…',
  'chromeProfiles.newPlaceholder': 'Nazwa profilu Chrome (litery, cyfry, - i _)',
  'chromeProfiles.newCreate': 'Utwórz',
  'chromeProfiles.newCancel': 'Anuluj',
  'chromeProfiles.newFailed': 'Nie udało się utworzyć profilu.',
  'chromeProfiles.liveProfile': 'Live Chrome (Twoja przeglądarka)',
  'chromeProfiles.liveDesc': 'Połącz z własnym uruchomionym Chrome — wymaga jednorazowego włączenia chrome://inspect/#remote-debugging.',
  'chromeProfiles.liveConfirm': 'Dać agentowi tego obszaru roboczego dostęp do CAŁEGO Twojego Chrome — wszystkich kart i logowań? Chrome dodatkowo zapyta o zgodę przy każdym połączeniu.',
  'chromeProfiles.liveConfirmYes': 'Podłącz live',
  'chromeProfiles.liveConfirmCancel': 'Anuluj',
  'settings.browserLightweight': 'Lekkie przeglądarki w tle',
  'settings.browserLightweightDesc': 'Ogranicz zużycie CPU przez wbudowane panele przeglądarki, które nie są widoczne (ukryte obszary robocze, oddalone panele, zminimalizowane okno). Automatyzacja (MCP/zrzuty ekranu) nadal działa pełną prędkością. Zmniejsza tylko CPU, nie pamięć.',
  'settings.browserDiscard': 'Odrzucaj ukryte przeglądarki (zwalnia pamięć)',
  'settings.browserDiscardDesc': 'Gdy panel przeglądarki pozostaje niewidoczny przez 5 minut, wyładuj go całkowicie, aby odzyskać pamięć. Strona wczytuje się ponownie po powrocie (pozycja przewijania i niezapisane dane formularza są tracone). Panele odtwarzające dźwięk nigdy nie są odrzucane; automatyzacja budzi odrzucony panel automatycznie.',
  'settings.siteMemory': 'Pamięć witryn',
  'settings.siteMemoryDesc': 'Zapamiętuj, co poszło nie tak w danej witrynie — przerwane odtwarzanie, host, który się nie wczytał — i przypominaj o tym, gdy przeglądarka trafi tam następnym razem. Zapisywane per przestrzeń robocza, jeden plik na domenę, zapominane po 60 dniach bez powtórki. Wyłączenie zatrzymuje zarówno zapisywanie, jak i przypominanie; to, co już zapisano, nadal można usunąć.',
  'settings.browserSectionRuntime': 'Działanie przeglądarki',
  'settings.browserSectionKnowledge': 'Wiedza agenta o witrynach',
  'settings.siteGuides': 'Przewodniki po witrynach',
  'settings.siteGuidesDesc': 'Gdy przeglądarka trafi na stronę pasującą do notatki w folderze site-guides katalogu danych wmux, poinformuj agenta, że taka notatka istnieje i gdzie się znajduje. Przekazywany jest tylko tytuł i ścieżka, nigdy treść notatki. Każde narzędzie z uprawnieniem do odczytu przeglądarki może zapytać, które notatki pasują do adresu URL, i poznać ich tytuły oraz ścieżki, ale nie ich treść. Domyślnie wyłączone. Włącza się automatycznie przy pierwszym wyborze przeglądarki agenta Chrome, a potem pozostaje tak, jak je ustawisz.',
  'settings.updates': 'Aktualizacje',
  'settings.wmuxUpdates': 'Aktualizacje wmux',
  'settings.updateFailed': 'Nie udało się sprawdzić aktualizacji',
  'settings.lastCheckedNever': 'Ostatnio sprawdzono: nigdy',
  'settings.installUpdate': 'Zainstaluj aktualizację',
  'settings.retryCheck': 'Spróbuj ponownie',
  'settings.fontSize': 'Rozmiar czcionki',
  'settings.fontSizeRange': 'zakres 8~24',
  'settings.fontFamily': 'Rodzina czcionek',
  'settings.fontFamilyDesc': 'Dowolna zainstalowana czcionka — wpisz nazwę lub wybierz jedną',
  'settings.fontFamilyPlaceholder': 'Wpisz lub wybierz czcionkę…',
  'settings.fontCustom': 'Niestandardowa czcionka…',
