  'settings.layout': 'Układ',
  'settings.chromePreset': 'Widoczność interfejsu',
  'settings.chromePresetMinimal': 'Zastosuj Minimalny',
  'settings.chromePresetStandard': 'Przywróć Standardowy',
  'settings.chromePresetApplied': 'Zaktualizowano widoczność interfejsu.',
  'settings.uiScale': 'Skala interfejsu',
  'settings.uiScaleDesc': 'Skaluj cały interfejs — przydatne na ekranach o wysokiej DPI. Restart nie jest wymagany.',
  'settings.sidebarPosition': 'Pozycja paska bocznego',
  'settings.sidebarPositionDesc': 'Po lewej lub po prawej stronie obszaru terminala',
  'settings.sidebarAttentionFirst': 'Wiersze czekające na Ciebie u góry',
  'settings.sidebarAttentionFirstDesc': 'Przenoś na górę paska bocznego przestrzenie robocze, których agent czeka na Ciebie. Domyślnie wyłączone: wiersze zostają tam, gdzie je przeciągniesz. Gdy jest włączone, zmiana kolejności przeciąganiem jest wstrzymana.',
  'settings.sidebarSort': 'Kolejność przestrzeni roboczych',
  'settings.sidebarSortDesc': 'Jak pasek boczny układa przestrzenie robocze. Uwaga (domyślnie) stawia najpierw to, co czeka na Ciebie, potem błędy, zakończone, działające, niepotwierdzone i bezczynne, a lista przestawia się dopiero po krótkiej przerwie albo gdy wskaźnik ją opuści. Ręczna zachowuje kolejność z przeciągania. W każdym trybie przestrzenie przypięte na górze zostają pierwsze, w nadanej przez Ciebie kolejności. Zmiana kolejności przeciąganiem działa w trybie Ręczna, a wśród przypiętych w każdym trybie.',
  'settings.sidebarSortManual': 'Ręczna',
  'settings.sidebarSortAttention': 'Uwaga',
  'settings.sidebarSortRecent': 'Ostatnia aktywność',
  'settings.sidebarShowExplorerButton': 'Pokaż przycisk "Otwórz w Eksploratorze plików"',
  'settings.sidebarShowExplorerButtonDesc': 'Pokazuj przycisk folderu w wierszach obszarów roboczych na pasku bocznym. Akcja pozostaje dostępna w menu kontekstowym wiersza.',
  'settings.sidebarShowCopyInfoButton': 'Pokaż przycisk "Kopiuj informacje o sesji"',
  'settings.sidebarShowCopyInfoButtonDesc': 'Pokazuj w wierszach obszarów roboczych na pasku bocznym przycisk kopiujący informacje o sesji.',
  'settings.sidebarShowPorts': 'Pokaż numery portów',
  'settings.sidebarShowPortsDesc': 'Pokazuj numery nasłuchujących portów w wierszach obszarów roboczych na pasku bocznym.',
  'settings.sidebarShowPaneCoordinates': 'Pokaż koordynaty pane\'ów',
  'settings.sidebarShowPaneCoordinatesDesc': 'Pokazuj w liście agentów wygenerowany koordynat w stylu w1-2 dla pane\'ów bez nadanej etykiety. Domyślnie włączone. Pane, który nazwałeś, zawsze pokazuje swoją etykietę niezależnie od tego ustawienia.',
  'settings.attentionBlink': 'Mruganie uwagi',
  'settings.attentionBlinkDesc': 'Jak miga wiersz paska bocznego czekający na pytanie lub zatwierdzenie, gdy jego obszar roboczy nie jest na ekranie. Raz + przypomnienie (domyślnie) miga na początku oczekiwania, a potem w każdym odstępie. Ograniczenie ruchu wyłącza każde mruganie.',
  'settings.attentionBlinkOff': 'Wył.',
  'settings.attentionBlinkOnce': 'Raz',
  'settings.attentionBlinkRemind': 'Raz + przypomnienie',
  'settings.attentionBlinkContinuous': 'Ciągle',
  'settings.attentionBlinkRemindEvery': 'Przypominaj co',
  'settings.attentionBlinkRemind30s': '30 s',
  'settings.attentionBlinkRemind1m': '1 min',
  'settings.attentionBlinkRemind5m': '5 min',
  'settings.attentionBlinkFinished': 'Zakończone tury',
  'settings.attentionBlinkFinishedDesc': 'Zakończona tura, której jeszcze nie oglądano, pokazuje małą kropkę zamiast ramki „potrzebuje cię”. Mrugnij raz sprawia też, że wiersz mignie po zakończeniu.',
  'settings.fleetLayout': 'Układ Floty',
  'settings.fleetLayoutDesc': 'Pokazuj Flotę jako jedną listę wymagających uwagi albo jako tablicę z kolumnami Pracuje, Czeka na Ciebie, Zakończone i Bezczynny. Ten sam przełącznik jest w nagłówku Floty.',
  'settings.attentionBlinkFinishedDot': 'Tylko kropka',
  'settings.attentionBlinkFinishedPulse': 'Mrugnij raz',
  'settings.windowGlass': 'Szkło okna',
  'settings.windowGlassDesc': 'Jak bardzo pulpit prześwituje przez pasek boczny i krawędź okna. Panele i terminale pozostają nieprzezroczyste. Tylko macOS.',
  'settings.windowGlassOff': 'Wył.',
  'settings.windowGlassSoft': 'Delikatne',
  'settings.windowGlassClear': 'Przejrzyste',
  'settings.sidebarLeft': 'Lewo',
  'settings.sidebarRight': 'Prawo',
  'settings.multiviewArrangement': 'Układ multiview',
  'settings.multiviewArrangementDesc': 'Jak obszary robocze są kafelkowane, gdy kilka jest pokazywanych naraz. Auto dopasowuje je do siatki; Kolumny ustawia je obok siebie; Wiersze układa je pionowo.',
  'settings.multiviewAuto': 'Auto',
  'settings.multiviewColumns': 'Kolumny',
  'settings.multiviewRows': 'Wiersze',
  'settings.paneActionsVisible': 'Przyciski akcji panelu',
  'settings.paneNewTerminalButton': 'Przycisk nowego terminala na pasku kart',
  'settings.paneNewTerminalButtonDesc':
    'Dodaje +, który umieszcza DRUGI terminal w tym panelu. wmux jest zbudowany wokół zasady jeden panel = jeden terminal — podział to zwykły sposób na kolejny — więc domyślnie jest to wyłączone. Ctrl+T robi to samo bez przycisku.',
  'settings.paneActionsVisibleDesc': 'Pokaż przyciski nowego terminala, podziału i nowej przeglądarki na pasku kart każdego panelu.',
  'settings.chatView': 'Widok czatu dla sesji Claude Code (eksperymentalny)',
  'settings.chatViewDesc': 'Dodaje przełącznik Terminal / Czat do lokalnych paneli Claude Code. Domyślnie wyłączony, dopóki renderowanie markdown i wysyłanie są testowane; Terminal działa bez zmian.',
  'settings.titlebarClock': 'Zegar na pasku tytułu',
  'settings.titlebarClockDesc':
    'Domyślnie wyłączony — system i tak pokazuje godzinę. Włącz, jeśli używasz wmux na pełnym ekranie z ukrytym paskiem zadań.',
  'settings.titlebarVitals': 'Zawsze pokazuj pamięć i CPU',
  'settings.titlebarVitalsDesc':
    'Domyślnie wyłączone — wskaźniki pamięci i CPU pojawiają się wtedy tylko przy dużym zużyciu pamięci. Włącz, aby oba były stale widoczne na pasku tytułu.',
  'settings.currentVersion': 'Bieżąca',
  'settings.latestVersion': 'Najnowsza',
  'settings.updateReady': 'Aktualizacja gotowa',
  'settings.updateEndsSessions': 'Instalacja zamyka każdy panel.',
  'update.installFailed': 'Nie udało się zainstalować aktualizacji. {error}',
