  'settings.unknownError': 'Nieznany błąd',
  'settings.notificationBehavior': 'Zachowanie powiadomień',
  'settings.soundDesc': 'Web Audio API — bez plików zewnętrznych',
  'settings.toast': 'Powiadomienia toast',
  'settings.toastDesc': 'Pokaż toast po zakończeniu pracy agenta',
  'settings.ring': 'Animacja obramowania',
  'settings.ringDesc': 'Pulsowanie obramowania na panelach z nieprzeczytanymi powiadomieniami',
  // Notification system expansion (T12)
  'settings.paneRing': 'Obramowanie panelu przy nowych powiadomieniach',
  'settings.paneRingDesc': 'Podświetla niebieskim obramowaniem panel, który otrzymał powiadomienie.',
  'settings.paneGlowDim': 'Jasność panelu z nieprzeczytanym',
  'settings.paneGlowDimDesc': 'Jak jasny pozostaje panel, gdy trzyma nieprzeczytaną poświatę. 100% wyłącza przyciemnianie, więc nieaktywne sesje zostają w pełni czytelne; 60% to klasyczny przyciemniony wygląd.',
  'settings.paneFlash': 'Efekt błysku przy nowym powiadomieniu',
  'settings.paneFlashDesc': 'Odtwarza 500ms błysk przed stałą poświatą. Pomija błysk, jeśli wyłączony (od razu poświata).',
  'settings.taskbarFlash': 'Migaj paskiem zadań, gdy okno nie ma fokusu',
  'settings.taskbarFlashDesc': 'Wywołuje sygnał paska zadań Windows, gdy przychodzi powiadomienie, a wmux jest ukryty.',
  'settings.notificationSoundChoice': 'Dźwięk powiadomienia',
  'settings.notificationSoundChoiceDesc': 'domyślny = odtwórz systemowy dźwięk powiadomienia. brak = cisza.',
  'settings.notificationSoundChoiceDefault': 'Domyślny',
  'settings.notificationSoundChoiceNone': 'Brak',
  'settings.notificationCategories': 'Kategorie powiadomień',
  'settings.notificationCategoriesDesc': 'Wyłącz kategorię, aby wyciszyć jej toasty, dźwięki, obramowania i miganie paska zadań. Wyciszone kategorie nadal pojawiają się w panelu powiadomień.',
  'settings.notificationCategory.agent-turn': 'Tura agenta zakończona',
  'settings.notificationCategory.agent-turn.desc': 'Główny agent zakończył swoją turę i jest gotowy na wejście.',
  'settings.notificationCategory.subagent': 'Subagent zakończony',
  'settings.notificationCategory.subagent.desc': 'Subagent zakończył swoją turę. Najgłośniejsza kategoria przy pracy równoległej. Wymaga mostka hooków Claude Code — bez niego tury subagentów są zgłaszane jako zwykłe tury agenta.',
  'settings.notificationCategory.approval': 'Oczekiwanie na zatwierdzenie',
  'settings.notificationCategory.approval.desc': 'Agent jest zablokowany i czeka na Ciebie. Zostaw to włączone, chyba że obserwujesz panele bezpośrednio.',
  'settings.notificationCategory.terminal': 'Powiadomienia terminala',
  'settings.notificationCategory.terminal.desc': 'Powiadomienia pulpitu wysyłane przez programy terminalowe (OSC 9/99/777).',
  'settings.notificationCategory.system': 'System i zewnętrzne',
  'settings.notificationCategory.system.desc': 'Zakończenia procesów, alerty nadzoru, sygnały kanałów i zewnętrzne wywołania powiadomień.',
  'settings.perWorkspaceNotifications': 'Powiadomienia per obszar roboczy',
  'settings.perWorkspaceNotificationsDesc': 'Wycisz powiadomienia dla pojedynczych obszarów roboczych. Wyciszone obszary robocze nigdy nie generują toastów, obramowań, dźwięków ani migania paska zadań.',
  'settings.perWorkspaceNotificationsEmpty': 'Brak obszarów roboczych.',
  'settings.muteWorkspace': 'Wycisz powiadomienia dla {name}',
  'settings.prWake': 'Budź agenta przy zdarzeniach PR',
  'settings.prWakeDesc': 'Gdy obszar roboczy nie ma orkiestratora, wpisz jedną linię do panelu agenta, którego checkout jest gałęzią PR, gdy CI się nie powiedzie, ktoś inny skomentuje albo PR ma konflikt (a po włączeniu także, gdy testy przejdą). Linia zawiera tylko numer PR i to, co się stało. To własny agent właściciela PR, niezależny od głównego bota HQ i jego wyłącznika.',
  'settings.prWakeFailures': 'Błędy, recenzje, konflikty',
  'settings.prWakeChecksPassed': 'Testy przeszły',
  'settings.prWakeNotice': 'Nowość: gdy CI PR się nie powiedzie, ktoś inny skomentuje albo pojawi się konflikt scalania, wmux wpisze jedną linię do panelu agenta pracującego nad tym PR. Wyłączysz to dla obszaru roboczego w Ustawienia › Powiadomienia › Budź agenta przy zdarzeniach PR.',
  'settings.prWakeNoticeOpen': 'Otwórz ustawienia',
